head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * 주식발행관리 팝업창
 * 자식생성창 
 */
/**
 * @method
 * @name fn_OpenDetailIssMng
 * @description desc
 * @param {string} obj desc
 * @param {string} vSecuGrpId desc
 * @param {string} vBzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailIssMng = async function(obj, vSecuGrpId, vBzProcsNo) {
    var url = "/listingcommon/ULDSTF92002.gfm";
    var winTitle = $c.lce.fn_getSecuGrpNm(vSecuGrpId) + " 주식발행관리";
    //alert('[rame.FrameID]'+frame.FrameID);
    if (obj.getValue() == "") {
        alert("[법인]을 선택하세요.");
        obj.focus();
        return;
    } else {
        if ($c.frame.path("/top") != undefined) {
            $c.frame.path("/top").WinOpen("ISS_MNG" + vBzProcsNo, url + "?" + frame.FrameID, winTitle, 1210, 765 + 30);
        } else {
            await $c.frame.CreateFrame("ISS_MNG" + vBzProcsNo, url, winTitle, 100, 10, 1210, 765 + 30, "window", 0, 0, true);
        }
    }
};







/**
 * 기안및 안내문작성팝업창
 */
/**
 * @method
 * @name fn_OpenDetailIsuProc
 * @description desc
 * @param {string} obj desc
 * @param {string} vSecuGrpId desc
 * @param {string} vTrdMktCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailIsuProc = async function(obj, vSecuGrpId, vTrdMktCd) {
    if (obj.getValue() == "") {
        alert("[법인]을 선택하세요.");
        obj.focus();
        return;
    } else {
        var pageId;
        if (vTrdMktCd == '1') {
            //유가 
            pageId = 'ULDSTF92020';
        } else if (vTrdMktCd == '2') {
            //코스닥
            pageId = 'ULDSTF92021';
        }
        await $c.frame.CreateDialogFrame(pageId, "/listingcommon/" + pageId + ".gfm", $c.lce.fn_getSecuGrpNm(vSecuGrpId) + " 안내문작성", 80, 160, 950, 410, "window");
    }
};



/**
 * 회사명/종목명 입력안내 팝업창
 */
/**
 * @method
 * @name fn_OpenDetailInputGuide
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailInputGuide = async function() {
    await $c.frame.CreateDialogFrame('ULDSTF92022', "/listingcommon/ULDSTF92022.gfm", "회사명/종목명 입력안내", 80, 50, 750, 615, "window");
};



/**
 * 신규상장시 변경전 주식수, 자본금 가져오기
 */
/**
 * @method
 * @name fn_bf_read_sync1
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} txb_ISU_CD desc
 * @param {string} edt_LIST_DD desc
 * @param {string} edt_BF_ACC_ISU_SHRS desc
 * @param {string} edt_BF_ACC_ISU_CAP desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_bf_read_sync1 = function(dtsObj, txb_ISU_CD, edt_LIST_DD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=BF_STKCERT_ISU_DTL_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_BF_ISU;
    url += "&ISU_CD=" + txb_ISU_CD.getValue();
    url += "&LIST_DD=" + edt_LIST_DD.getValue();
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    if (dtsObj.getTotalRow() > 0) {
        edt_BF_ACC_ISU_SHRS.setValue(dtsObj.getCellData(1, "BF_ACC_ISU_SHRS"));
        edt_BF_ACC_ISU_CAP.setValue(dtsObj.getCellData(1, "BF_ACC_ISU_CAP"));
    } else {
        //신규건...
        edt_BF_ACC_ISU_SHRS.setValue(0);
        edt_BF_ACC_ISU_CAP.setValue(0);
    }
};




/**
 * 변경전 주식수, 자본금 가져오기
 */
/**
 * @method
 * @name fn_bf_read_sync2
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} txb_ISU_CD desc
 * @param {string} edt_BF_ACC_ISU_SHRS desc
 * @param {string} edt_BF_ACC_ISU_CAP desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_bf_read_sync2 = function(dtsObj, txb_ISU_CD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP) {
    var url = "/Listing.do?method=searchIsuIssChgList";
    url += "&DIV_IDX=" + DIV_IDX_ISS_STK_HIST;
    url += "&TRS_IDX=" + TRS_IDX_NEWSEL2;
    url += "&ISU_CD=" + txb_ISU_CD.getValue();
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    if (dtsObj.getTotalRow() > 0) {
        edt_BF_ACC_ISU_SHRS.setValue(dtsObj.getCellData(1, "BF_ACC_ISU_SHRS"));
        edt_BF_ACC_ISU_CAP.setValue(dtsObj.getCellData(1, "BF_ACC_ISU_CAP"));
    } else {
        //신규건...
        edt_BF_ACC_ISU_SHRS.setValue(0);
        edt_BF_ACC_ISU_CAP.setValue(0);
    }
};





/**
 * DR인경우 그리드 설정을 변경
 */
/**
 * @method
 * @name fn_gridNameChange
 * @description desc
 * @param {string} vSecuGrpId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_gridNameChange = function(vSecuGrpId) {
    if (vSecuGrpId == SECUGRP_ID_DR) {
        grd_IssList.setColumnProp("PARVAL", "Show", false); //액면가
        grd_IssList.setColumnProp("CMSTK_ISU_SHRS", "Show", false); //총발행보통주식수
        grd_IssList.setColumnProp("PREFSTK_ISU_SHRS", "Show", false); //총발행우선주식수
        grd_IssList.setColumnProp("ISU_CAP", "Show", false); //증감상장자본금
        grd_IssList.setColumnProp("ACC_ISU_CAP", "Show", false); //변경후 상장자본금
        grd_IssList.setColumnProp("PREFSTK_TP_NM", "Show", false); //신형우선주여부
        grd_IssList.setColumnProp("STKCERT_KIND_NM", "Name", 'DR종류');
        grd_IssList.setColumnProp("ACC_ISU_SHRS", "Name", '총발행DR수');
        grd_IssList.setColumnProp("ISU_SHRS", "Name", '증감DR수');
        grd_IssRecv.setColumnProp("PARVAL", "Show", false); //액면가
        grd_IssRecv.setColumnProp("ACC_ISU_CAP", "Show", false); //총발행자본금
        grd_IssRecv.setColumnProp("STKCERT_KIND_NM", "Name", 'DR종류');
        grd_IssRecv.setColumnProp("ISU_SHRS", "Name", '발행DR수');
    } else {
        grd_IssList.setColumnProp("PARVAL", "Show", true); //액면가
        grd_IssList.setColumnProp("CMSTK_ISU_SHRS", "Show", true); //총발행보통주식수
        grd_IssList.setColumnProp("PREFSTK_ISU_SHRS", "Show", true); //총발행우선주식수
        grd_IssList.setColumnProp("ISU_CAP", "Show", true); //증감상장자본금
        grd_IssList.setColumnProp("ACC_ISU_CAP", "Show", true); //변경후 상장자본금
        grd_IssList.setColumnProp("PREFSTK_TP_NM", "Show", true); //신형우선주여부
        grd_IssList.setColumnProp("STKCERT_KIND_NM", "Name", '주식종류');
        grd_IssList.setColumnProp("ACC_ISU_SHRS", "Name", '총발행주식수');
        grd_IssList.setColumnProp("ISU_SHRS", "Name", '증감주식수');
        grd_IssRecv.setColumnProp("PARVAL", "Show", true); //액면가
        grd_IssRecv.setColumnProp("ACC_ISU_CAP", "Show", true); //총발행자본금
        grd_IssRecv.setColumnProp("STKCERT_KIND_NM", "Name", '주식종류');
        grd_IssRecv.setColumnProp("ISU_SHRS", "Name", '발행주식수');
    }
};




